module RAM(
    input clk, rst_n, write_en, read_en,
    input [$clog2(DEPTH)-1:0] write_addr, read_addr,
    input [WIDTH-1:0] write_data,
    output reg [WIDTH-1:0] read_data
);

parameter WIDTH = 6;
parameter DEPTH = 8;

// Define internal RAM register
reg [WIDTH-1:0] internal_RAM [DEPTH-1:0];

// Initialize internal_RAM to 0
integer i;
initial begin
    for (i = 0; i < DEPTH; i = i + 1) begin
        internal_RAM[i] = {WIDTH{1'b0}};
    end
end

// Write operation
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            internal_RAM[i] <= {WIDTH{1'b0}};
        end
    end else if (write_en) begin
        internal_RAM[write_addr] <= write_data;
    end
end

// Read operation
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        read_data <= {WIDTH{1'b0}};
    end else if (read_en) begin
        read_data <= internal_RAM[read_addr];
    end
end

endmodule
